my $DATE_NC = "(?<![A-Za-z0-9])$DATE_INNER(?![A-Za-z0-9])";
my $pat = "^(?=.*$IP).*$DATE_CAP(?!.*$DATE_NC).*$";
print "$pat\n\n";
my @tests = (
  ["2024-01-15 Connection from 192.168.1.1 established", "2024-01-15"],
  ["Connection from 192.168.1.1 on 2024-01-15 and 2024-02-20 done", "2024-02-20"],
