  ["2024-02-30 from 1.2.3.4 invalid feb30", undef],
  ["2024-04-31 from 1.2.3.4 invalid apr31", undef],
  ["2024-04-30 from 1.2.3.4 valid", "2024-04-30"],
  ["2024-01-31 from 1.2.3.4 valid jan31", "2024-01-31"],
  ["2023-02-29 from 8.8.8.8 valid per task", "2023-02-29"],
  ["2024-13-01 from 1.1.1.1 invalid month", undef],
  ["2024-00-10 from 1.1.1.1 invalid month", undef],
  ["2024-01-00 from 1.1.1.1 invalid day", undef],
  ["2024-01-32 from 1.1.1.1 invalid day", undef],
  ["a2024-01-15 from 1.1.1.1", undef],
  ["2024-01-15a from 1.1.1.1", undef],
  ["2024-01-15 from 01.02.03.04 leading zeros", undef],
  ["2024-01-15 from 256.1.1.1 invalid IP", undef],
  ["2024-01-15 from a192.168.1.1 preceded alnum", undef],
  ["2024-01-15 from 192.168.1.1a followed alnum", undef],
  ["2024-05-05 IP 0.0.0.0 valid", "2024-05-05"],
  ["2024-05-05 IP 255.255.255.255 valid", "2024-05-05"],
  ["2024-06-15 IP 1.2.3.4 and then 2024-02-30 invalid tail", "2024-06-15"],
  ["192.168.001.001 with 2024-05-05 leading zeros IP invalid", undef],
  ["dates 2024-01-01 and 2024-01-02 with IP 9.9.9.9", "2024-01-02"],
  ["2024-01-01 IP 1.1.1.1 2024-02-30 invalid then end", "2024-01-01"],
  ["  2024-07-04  from 10.10.10.10  ", "2024-07-04"],
  ["2024-07-04,from 10.10.10.10;", "2024-07-04"],
  ["(2024-07-04) [10.10.10.10]", "2024-07-04"],
  ["2024-07-04 from 10.10.10.10 extra 2024-13-40 invalid", "2024-07-04"],
);
my $fail=0;
for my $t (@tests) {
  my ($line, $exp) = @$t;
  my @m;
  my $tmp = $line;
  while ($tmp =~ /$pat/mg) { push @m, $1; }
  my $got = @m ? $m[0] : undef;
  my $ok = (!defined $exp && !defined $got) || (defined $exp && defined $got && $exp eq $got);
  # also check count==1 when defined
  if (defined $got && @m != 1) { $ok = 0; }
  printf("%s line=%s got=%s exp=%s (n=%d)\n", $ok?"OK  ":"FAIL", $line, defined $got?$got:"<none>", defined $exp?$exp:"<none>", scalar @m);
  $fail++ unless $ok;
}
print "\nmultiline test:\n";
my $log = "2024-01-01 start 10.0.0.1 middle 2024-06-01 end\nsecond line 2024-03-03 no ip\nthird 192.168.0.1 date 2023-12-31\n";
my @m; while ($log =~ /$pat/mg) { push @m, $1; }
print join(",", @m), " expected 2024-06-01,2023-12-31\n";
print "fails=$fail\n";
PL
